        let rest = seq.take(n - 1);
        let last = seq.index(n - 1);
        // IH: seq_to_set_rec(rest) == { x | Seq.contains(rest,x) }
        seq_to_set_equal_rec(rest);

        // By definition of seq_to_set_rec on `seq`:
        //    seq_to_set_rec(seq) = seq_to_set_rec(rest).insert(last)
        //
        // Also, { x | Seq.contains(seq,x) }
        //    = { x | Seq.contains(rest.push(last), x) }
        //    = { x | Seq.contains(rest,x) } ⋃ { last }
