        // Therefore they coincide. We can appeal to lemma_seq_push_to_set_insert
        // to formalize that `.insert(last)` matches extending the comprehension.
        lemma_seq_push_to_set_insert(rest, last);

        // Final conclusion:
        assert(seq_to_set_rec(seq)
             == Set::new(|x: A| Seq::contains(seq, x)));
